    } catch (Exception e) {
      throw new GdxRuntimeException("Error getting input stream from socket.", e);
    }
  }

  @Override
  public OutputStream getOutputStream() {
    try {
      return socket.getOutputStream();
    } catch (Exception e) {
      throw new GdxRuntimeException("Error getting output stream from socket.", e);
    }
  }

  @Override
  public String getRemoteAddress() {
    return socket.getRemoteSocketAddress().toString();
  }

  @Override
  public void dispose() {
    if (socket != null) {
      try {
        socket.close();
        // Do not assign null to socket to satisfy NullAway's non-null field contract.
      } catch (Exception e) {
        throw new GdxRuntimeException("Error closing socket.", e);
      }
    }
  }
}
